components.css:
.button{
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  min-height: 54px;
  padding: 15px 23px;
  font-size: 12px;
  font-weight: 450;
  border: 1px solid #163024;
  background: #163024;
  color: #f7f8f3;
  line-height: 1.45;
  transition:
    background-color 0.2s ease,
    color 0.2s ease;
  max-width: 100%;
  text-align: left;
}
